begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);select set_config('request.jwt.claim.role','authenticated',true);
create function pg_temp.crm_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.crm_denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpected permission %',label;end$$;
create function pg_temp.crm_req(n integer) returns uuid language sql as $$select ('cb300000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
grant execute on all functions in schema pg_temp to authenticated,anon;
insert into branches(id,code,name) values('cb100000-0000-0000-0000-000000000001','CRM-A','CRM ficticia A'),('cb100000-0000-0000-0000-000000000002','CRM-B','CRM ficticia B');
insert into auth.users(id,email) values('cb200000-0000-0000-0000-000000000001','crm-sales-a@example.invalid'),('cb200000-0000-0000-0000-000000000002','crm-sales-b@example.invalid');
insert into profiles(id,full_name,branch_id,active) values('cb200000-0000-0000-0000-000000000001','Comercial ficticio A','cb100000-0000-0000-0000-000000000001',true),('cb200000-0000-0000-0000-000000000002','Comercial ficticio B','cb100000-0000-0000-0000-000000000002',true);
insert into user_roles(user_id,role_id,branch_id) select p.id,r.id,p.branch_id from profiles p cross join roles r where p.id in ('cb200000-0000-0000-0000-000000000001','cb200000-0000-0000-0000-000000000002') and r.code='ASISTENTE_COMERCIAL';
insert into customers(id,name) values('cb400000-0000-0000-0000-000000000001','Cliente ficticio A'),('cb400000-0000-0000-0000-000000000002','Cliente ficticio B');
insert into commercial_locations(branch_id,customer_id,address,created_by) values('cb100000-0000-0000-0000-000000000001','cb400000-0000-0000-0000-000000000001','Dirección ficticia A','cb200000-0000-0000-0000-000000000001'),('cb100000-0000-0000-0000-000000000002','cb400000-0000-0000-0000-000000000002','Dirección ficticia B','cb200000-0000-0000-0000-000000000002');
select pg_temp.crm_ok((select not enabled from app_feature_flags where key='commercial_crm'),'CRM flag defaults off');
set local role authenticated;select set_config('request.jwt.claim.sub','cb200000-0000-0000-0000-000000000001',true);
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"Persona ficticia"}}',pg_temp.crm_req(1))$q$,'disabled CRM blocks definitive changes');
reset role;update app_feature_flags set enabled=true where key='commercial_crm';set local role authenticated;
select pg_temp.crm_ok((crm_catalog('cb100000-0000-0000-0000-000000000001')->>'can_write')::boolean,'commercial assistant can use CRM in assigned branch');
select pg_temp.crm_ok(jsonb_array_length(crm_catalog('cb100000-0000-0000-0000-000000000001')->'customers')=1 and crm_catalog('cb100000-0000-0000-0000-000000000001')->'customers'->0->>'id'='cb400000-0000-0000-0000-000000000001','CRM catalog shows only customer linked to requested branch');
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"No debe guardarse","customer_id":"cb400000-0000-0000-0000-000000000002"}}',pg_temp.crm_req(20))$q$,'CRM save rejects a foreign-branch customer even with known identifier');
select pg_temp.crm_denied($q$select crm_catalog('cb100000-0000-0000-0000-000000000002')$q$,'catalog excludes other branch');
select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"Persona ficticia A","email":"equipo@example.invalid","phone":"8090000000","center":"Centro ficticio","objective":"Presentar servicios"}}',pg_temp.crm_req(1))->>'id' as crm_one \gset
select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"Persona ficticia A","email":"equipo@example.invalid","phone":"8090000000","center":"Centro ficticio","objective":"Presentar servicios"}}',pg_temp.crm_req(1));
select pg_temp.crm_ok((select count(*)=1 from crm_contacts),'same request creates one contact');
select pg_temp.crm_ok((select count(*)=1 from crm_history),'same request creates one definitive history event');
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"Otra persona"}}',pg_temp.crm_req(1))$q$,'request cannot be reused with other fields');
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"Persona ficticia B","email":"equipo@example.invalid"}}',pg_temp.crm_req(2))$q$,'shared email requires explicit duplicate decision');
select pg_temp.crm_ok(jsonb_array_length(crm_review('cb100000-0000-0000-0000-000000000001','[{"data":{"full_name":"Persona ficticia B","email":"equipo@example.invalid"}}]')->0->'matches')=1,'review returns possible match without merging people');
select crm_action('cb100000-0000-0000-0000-000000000001','SAVE','{"fields":{"full_name":"Persona ficticia B","email":"equipo@example.invalid"},"allow_duplicate":true,"duplicate_reason":"Dos personas del mismo centro"}',pg_temp.crm_req(2));
select pg_temp.crm_ok((select count(*)=2 from crm_contacts),'justified shared email keeps two separate cards');
select pg_temp.crm_denied($q$update crm_contacts set full_name='Sin auditoría'$q$,'browser cannot bypass audited contact RPC');
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','IMPORT','{"rows":[{"data":{"full_name":"Referidor que no debe persistir","kind":"REFERIDOR"},"decision":"CREATE","approved":true},{"data":{"full_name":""},"decision":"CREATE","approved":true}]}',pg_temp.crm_req(3))$q$,'invalid import rolls back entire batch');
select pg_temp.crm_ok((select count(*)=2 from crm_contacts) and not exists(select 1 from medical_referrers where full_name='Referidor que no debe persistir'),'invalid batch leaves contacts and referral directory unchanged');
select crm_action('cb100000-0000-0000-0000-000000000001','IMPORT','{"rows":[{"data":{},"decision":"SKIP"},{"data":{"full_name":"Referidor ficticio","kind":"REFERIDOR","specialty":"Especialidad ficticia","phone":"8290000000","initial_note":"Nota comercial previa importada"},"decision":"CREATE","approved":true,"file":"demo.csv","row":3}]}',pg_temp.crm_req(4));
select pg_temp.crm_ok((select count(*)=3 from crm_contacts),'excluded error row does not block valid import');
select pg_temp.crm_ok(exists(select 1 from crm_contacts c join medical_referrers r on r.id=c.referrer_id where c.full_name='Referidor ficticio' and r.branch_id=c.branch_id and r.specialty='Especialidad ficticia'),'new referrer has linked canonical directory identity');
select crm_action('cb100000-0000-0000-0000-000000000001','IMPORT',jsonb_build_object('rows',jsonb_build_array(jsonb_build_object('data',jsonb_build_object('full_name','Referidor ficticio actualizado','kind','PROSPECTO','stage','PROSPECTO','email',''),'decision','UPDATE','approved',true,'target_id',(select id from crm_contacts where full_name='Referidor ficticio'),'revision',1,'empty_fields',jsonb_build_array('kind','stage','preferred_channel')))),pg_temp.crm_req(14));
select pg_temp.crm_ok(exists(select 1 from crm_contacts where full_name='Referidor ficticio actualizado' and kind='REFERIDOR'),'empty import type preserves existing referrer identity');
select pg_temp.crm_ok(jsonb_array_length(crm_review('cb100000-0000-0000-0000-000000000001','[{"data":{"full_name":"Nombre distinto","phone":"+1 (809) 000-0000"}}]')->0->'matches')>=1,'Dominican phone variants suggest same contact');
select pg_temp.crm_ok(exists(select 1 from crm_activities where channel='NOTA' and notes='Nota comercial previa importada'),'spreadsheet notes become preserved contact history');
select pg_temp.crm_ok(exists(select 1 from crm_history where action='IMPORTAR_FILA' and metadata->>'file'='demo.csv' and metadata->>'row'='3'),'file and original row are in definitive history');
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','IMPORT','{"rows":[{"data":{"full_name":"Pendiente"},"decision":"CREATE","approved":false}]}',pg_temp.crm_req(5))$q$,'unapproved import cannot commit');
select pg_temp.crm_denied(format($q$select crm_action('cb100000-0000-0000-0000-000000000001','SAVE',jsonb_build_object('id',%L,'revision',0,'fields',jsonb_build_object('full_name','Intento obsoleto')),pg_temp.crm_req(6))$q$,:'crm_one'),'stale edit rejected');
select crm_action('cb100000-0000-0000-0000-000000000001','ACTIVITY',jsonb_build_object('contact_id',:'crm_one','revision',1,'channel','VISITA','occurred_at',now()-interval '1 hour','notes','Visita ficticia registrada','outcome','Solicitó información','follow_up_at',now()+interval '2 days'),pg_temp.crm_req(7));
select pg_temp.crm_ok((select count(*)=1 and bool_and(created_by=auth.uid()) from crm_activities where contact_id=:'crm_one'),'visit notes preserve actual account author');
select pg_temp.crm_ok((select revision=2 and follow_up_at>now() from crm_contacts where id=:'crm_one'),'visit updates next followup with new revision');
select pg_temp.crm_denied($q$update crm_activities set notes='Reescritura'$q$,'visit history cannot be overwritten by browser');
select pg_temp.crm_denied($q$select crm_action('cb100000-0000-0000-0000-000000000001','SERVICE','{"code":"NO","name":"No autorizado"}',pg_temp.crm_req(8))$q$,'assistant cannot alter service catalog');
select set_config('request.jwt.claim.sub','cb200000-0000-0000-0000-000000000002',true);
select pg_temp.crm_ok((select count(*)=0 from crm_contacts) and (select count(*)=0 from crm_activities) and (select count(*)=0 from crm_history),'other branch cannot read cards activities or audit');
reset role;update profiles set active=false where id='cb200000-0000-0000-0000-000000000001';set local role authenticated;select set_config('request.jwt.claim.sub','cb200000-0000-0000-0000-000000000001',true);
select pg_temp.crm_ok((select count(*)=0 from crm_contacts),'inactive account loses CRM access');
reset role;set local role anon;select pg_temp.crm_denied($q$select * from crm_contacts$q$,'anonymous cannot read commercial contacts');select pg_temp.crm_denied($q$select crm_catalog('cb100000-0000-0000-0000-000000000001')$q$,'anonymous cannot enumerate CRM catalog');
rollback;
